  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Analyze the phrase "That will not only echo in my heart and mind." What is the nature of this "echo," and how does it motivate the poet?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Discuss the importance of self-perception and inner resolve as portrayed in the poem.$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$How does the poem implicitly critique the idea of giving up prematurely?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$What is the significance of the poem being presented in an English-8 context? What learning objectives might it serve?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Reflect on the title "Cordova Smart Class Software" and "NEP Guidelines." How do these elements suggest a modern, educational context for the poem's study?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true);
INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('472ff205-73c0-4498-845a-a3d5e2932d34', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Rina is a student who often hesitates to participate in class discussions, even when she knows the answer, fearing she might make a mistake. She reads 'Bravery Pledge' and is particularly struck by the line, 'Bravery is living despite the fear, And doing what needs to be done Even though you are scared.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('2cc29ae3-e17f-43a0-a194-130b00e23a1f', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$The school is organizing a talent show, and David, a talented singer, is reluctant to sign up because he fears public judgment. He recalls the poet's vow: 'I will stand up and be counted. Even when I’m one of the few or standing all by myself.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('56c58256-33c8-498f-af04-ef9d8b872bb6', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Maria has a dream of becoming an artist, but her parents encourage her to pursue a more 'stable' career. She feels torn, remembering the poet's declaration: 'I vow to live my dreams no matter what; I will stand up and be counted.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('102a9463-7112-4d33-843d-a749898afa6f', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$A group of friends is planning an adventurous trek, but one friend, Tom, is scared of heights. He remembers the 'batter's box' metaphor from 'Bravery Pledge' and the line, 'And I will not cower at the thought of being hit.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('04f71147-fcf5-4c3b-8b2e-1eeafc36160b', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Sarah often finds herself regretting past decisions, thinking 'what if I had done this instead?' The poem states, 'I will not look back at the end of my life Thinking of what could have been.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('b54a87f7-00c1-4367-b560-602e0160620e', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$A new student, Alex, is struggling to make friends and feels isolated in his new school environment. He reads the line, 'Even when I’m one of the few or standing all by myself.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('b70123bf-a12d-43d5-b1b5-5ec17741f745', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$The school debate club is discussing a controversial topic, and one student, Ben, holds an unpopular opinion that he is hesitant to voice. He remembers the poet's resolve: 'I will proudly state before God and all who see This is who I am and what I want to be.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('72d15c2f-abb7-4992-8c5c-9016f7d47fbe', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Emily wants to try out for the school play but is worried about memorizing lines and performing in front of an audience. She reflects on the poem's message about doing what needs to be done despite fear.$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('41c75a54-6685-4a8b-9c03-ed4b854b0009', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$A local community project requires volunteers, but it involves tasks that are outside of Maya's comfort zone, making her apprehensive. She recalls the poem's emphasis on facing fears and making choices.$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('77535b58-eb41-4519-a10d-0a5238ad8697', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Liam is facing a difficult academic challenge and feels overwhelmed by the complexity of the subject. He remembers the pre-reading question: 'What inspires you to face difficulty in life with a positive attitude?'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('215b5f68-f6b7-412e-b911-5dfe24e1502e', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$During a group project, one team member, Chloe, is hesitant to present her innovative idea because she fears it might be criticized. She remembers the poet's resolve to 'stand up and be counted.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('3422bdab-df54-456a-9975-f60ef399c936', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Mark is considering applying for a leadership position, but he doubts his abilities and fears the responsibilities. He reflects on the poem's definition of bravery: 'Bravery is living despite the fear, And doing what needs to be done Even though you are scared.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('706d0f1e-93ca-4119-a962-c7a26adf2a33', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$The school newspaper needs a new editor, and while Jessica is highly qualified, she's worried about the time commitment and potential stress. She recalls the poet's vow: 'I vow to live my dreams no matter what.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('3df1653e-c133-4083-8666-247c3170d5ba', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Daniel has a unique hobby that he enjoys, but he's shy about sharing it with others, fearing they might not understand or might mock him. He remembers the poet's declaration: 'This is who I am and what I want to be.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('dba5f70d-af44-49d2-9530-12d55929ad0e', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$A school competition requires participants to perform a challenging task, and many students are hesitant. Lisa, however, remembers the 'Bravery Pledge' and its message about facing fears.$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('7f55d026-54b1-4df7-8aab-e1de9cb7de96', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Kevin often avoids trying new things because he's afraid of failure. He reads the poem's rejection of being 'content with what could have been, but never was.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('7312c862-7ddf-45f5-a72c-2bd005818181', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$A school project requires students to work in diverse groups, and some students are uncomfortable interacting with classmates they don't know well. The unit title is 'Sensitivity Towards All.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('a11c226f-f514-409b-80a9-da4543354f4b', '8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', '995323c5-784e-45a4-84e7-517dcd6d1b16', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Fiona is learning a new language and finds it difficult, often feeling discouraged by her mistakes. She recalls the learning outcome: 'learn new words and use them in sentences.'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-326Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
